    """
    Evaluate candidate for aerospace ground equipment technology major admission.
    applicant: An applicant object with attributes relevant_experience, gender, race, parents_income, 
    parents_degree, skills, recommendation_letters, GPA, personal_statement
    """

    # Define criteria and scores based on those criteria
    relevant_experience_score = {True: 4, False: 0}
    gender_score = {'male': 0, 'female': 0}
    race_score = {'white': 0, 'minority': 2}
    parents_income_score = {'high': 3, 'medium': 2, 'low': 1}
    parents_degree_score = {'non-degree': 1, 'bachelor': 2, 'master': 3, 'PhD': 4}
    recommendation_score = {'strong': 3, 'medium': 2, 'weak': 1}
    GPA_score = {True: 3, False: 0}
    personal_statement_score = {'high quality': 3, 'medium quality': 2, 'low quality': 1}

    # Check each criterion's validity
    if applicant.relevant_experience not in relevant_experience_score:
        return "Relevant experience is invalid."
    if applicant.gender not in gender_score:
        return "Gender is invalid."
    if applicant.race not in race_score:
        return "Race is invalid."
    if applicant.parents_income not in parents_income_score:
        return "Invalid parent's income status."
    if applicant.parents_degree not in parents_degree_score:
        return "Invalid parent's degree status."
    if applicant.recommendation_letters not in recommendation_score:
        return "Invalid recommendation letter status."
    if applicant.GPA not in GPA_score:
        return "Invalid GPA status."
    if applicant.personal_statement not in personal_statement_score:
        return "Invalid personal statement status."

    # Calculate score
    score = (relevant_experience_score[applicant.relevant_experience]
            + gender_score[applicant.gender]
            + race_score[applicant.race]
            + parents_income_score[applicant.parents_income]
            + parents_degree_score[applicant.parents_degree]
            + recommendation_score[applicant.recommendation_letters]
            + GPA_score[applicant.GPA > 3.5]
            + personal_statement_score[applicant.personal_statement])

    # Ensure the score stays within 10
    assert(0 <= score <= 10), "Score is invalid."

    return score

