def smallest_diff_pair(array1, array2):
    array1.sort()
    array2.sort()
    i = j = 0 
    diff = float('inf')
    pair = ()
    while(i<len(array1) and j<len(array2)):
        if(abs(array1[i]-array2[j])<diff):
            diff=abs(array1[i]-array2[j])
            pair= (array1[i],array2[j])
        if(array1[i]<array2[j]):
            i=i+1
        else:
            j=j+1
    return pair

