    """
    Evaluate candidates for early childhood and family studies major admission.
    applicant: An applicant object with attributes: personal_statement, GPA, gender, race, parents_income, parents_degree, recommendation_letters, skills, relevant_experience
    """
    score = 0
    # GPA
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Strong personal statement
    if applicant.personal_statement == 'high quality':
        score += 2
    elif applicant.personal_statement == 'medium quality':
        score += 1

    # Strong recommendation letters
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Skills relevant to the field
    relevant_skills = ['early childhood education', 'social work', 'family counseling']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2
    elif len(skill_matches) >= 1:
        score += 1

    # Relevant experience
    if applicant.relevant_experience >= 2:  # assuming this is number of years
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    # Parent's education level
    parent_degree_scores = {
        'non-degree': 0,
        'bachelor': 1,
        'master': 2,
        'PhD': 3
    }
    score += parent_degree_scores.get(applicant.parents_degree, 0)

    # Underrepresented groups
    underrepresented_genders = ['female', 'non-binary']
    underrepresented_races = ['native american', 'hispanic']
    if applicant.gender in underrepresented_genders:
        score += 1
    if applicant.race in underrepresented_races:
        score += 1

    # Parents income
    income_scores = {'low': 0, 'medium': 1, 'high': 2}
    score += income_scores.get(applicant.parents_income, 0)

    return score
